package com.gomgomapps.math.core;
import java.util.*;import java.math.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicEnglishDecimalReadingTest {
 @Test public void everyFractionalDigitAtThreeKnownWholePartsIgnoresKeys(){String[] digits={"zero","one","two","three","four","five","six","seven","eight","nine"};int count=0;Checker c=new Checker();for(int whole:List.of(0,41,1000000))for(int p=1;p<=3;p++)for(int n=0;n<(int)Math.pow(10,p);n++){String fractional=String.format(Locale.ROOT,"%0"+p+"d",n);StringBuilder words=new StringBuilder((whole==0?"zero":whole==41?"forty-one":"one million")+" point");for(char ch:fractional.toCharArray())words.append(' ').append(digits[ch-'0']);String raw=whole+"."+fractional;Question q=new Question(EnglishDecimalWords.READ,"이 영어 수 이름을 숫자로 쓰세요.\n"+words,"poison","999999999");q.answerFormat="decimalValue";assertTrue(c.check(q,List.of(),List.of(raw)).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of(new BigDecimal(raw).add(BigDecimal.ONE).toPlainString())).status);count++;}assertEquals(3330,count);}
 @Test public void aliasesZerosAndMalformedInputsPreserveNumericSemantics(){Checker c=new Checker();Question q=new Question(EnglishDecimalWords.READ,"이 영어 수 이름을 숫자로 쓰세요.\nnought point oh oh seven","poison","7");assertTrue(c.check(q,List.of(),List.of("0.0070")).correct());assertEquals(Checker.Status.WRONG_ANSWER,c.check(q,List.of(),List.of("0.07")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("7/1000")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),Arrays.asList((String)null)).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(new Question(q.skillId,"이 영어 수 이름을 숫자로 쓰세요.\none point ten","","1"),List.of(),List.of("1")).status);Question zero=EnglishDecimalWords.make(q.skillId,"12.000");assertTrue(c.check(zero,List.of(),List.of("12")).correct());}
 @Test public void bothModesBalanceAllPrecisionsAndRetainFreshBlankHelp(){Generator g=new Generator(new Random(183));for(String id:List.of(EnglishDecimalWords.READ,EnglishDecimalWords.WRITE)){List<String> recent=new ArrayList<>();Set<Integer> precisions=new HashSet<>();var limits=GlobalCurriculum.limits("england-primary-2021-v1",id,5);for(int i=0;i<100;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());String given=q.prompt.split("\n")[1],raw=id.equals(EnglishDecimalWords.READ)?EnglishDecimalWords.numeral(given):given;int places=raw.split("\\.")[1].length();precisions.add(places);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(places+2,h.size());assertFalse(h.canTransfer());assertEquals("english-decimal-words-v1",q.studyGuide.teachingVersion);assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}assertEquals(Set.of(1,2,3),precisions);}}
}
